local UIFeelingCommunicationDialog = Class("UIFeelingCommunicationDialog")

local PAGESTATE = {
    NORMAL = 1,      --正常
    AGAIN = 2,       --回溯  重新体验
    LOOKHISTORY = 3,       --查看历史
}

local UIFeelingCommunicationRoleNode = "Game.UI.Phone.News.UIFeelingCommunication.UIFeelingCommunicationRoleNode"
local UIFeelingCommunicationRightNode = "Game.UI.Phone.News.UIFeelingCommunication.UIFeelingCommunicationRightNode"

function UIFeelingCommunicationDialog:__init() 
    self._allCats = {}                       --所有的角色
    self._allChatInfos = {}                  --某个角色的所有聊天信息
    self._curCatId = nil                     --当前选中的角色
    self._pageState = nil                    --页面状态
    self._targetTopicId = nil                --回溯状态的默认话题
end

function UIFeelingCommunicationDialog:__delete()
    self._allCats = {}                       --所有的角色
    self._allChatInfos = {}                  --某个角色的所有聊天信息
    self._curCatId = nil                     --当前选中的角色
    self._pageState = nil                    --页面状态
    self._targetTopicId = nil                --回溯状态的默认话题
