function UIFeelingCommunicationDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self:FillSelf()
    end))
    return coWait
end

function UIFeelingCommunicationDialog:Awake()
    self.EventChageChatPageState = Events.AddListener(Constants.EventNames.ChageChatPageState, Bind(self, self.OnChageChatPageState))

    local argument = self.controller.Argument.parameters
    --如果指定人物聊话题 必须传参
    if argument then
        self._curCatId = checkString(argument.catId)
    end

    if not self._pageState then                       --默认都是正常来聊天
        self._pageState = Constants.CHATSOURCE.NORMAL               
    end

    self:InitData()
end

--初始化数据
function UIFeelingCommunicationDialog:InitData()
    if self._pageState == Constants.CHATSOURCE.NORMAL then
        self._allCats = PhoneUtils.GetAllUnlockCatIdArray()
        --没有默认选第一个
        if not self._curCatId then
            self._curCatId = self._allCats[1]
        end
    else
        self._allCats = {
            [1] = self._curCatId
        }
    end
end

function UIFeelingCommunicationDialog:FillSelf()
    if not self._isInitRoleView then
        self.LoopViewmessage:InitGridView(#self._allCats, Bind(self, self.OnGetRoleCellByIndex))
        self._isInitRoleView = true
    else
        GameUtils.ReloadData(self.LoopViewmessage, 0)
        GameUtils.ReloadData(self.LoopViewmessage, #self._allCats)
    end
end

function UIFeelingCommunicationDialog:OnGetRoleCellByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local id = self._allCats[index + 1]
    local cell = listView:NewListViewItem("itemcel")
    
    local scr = CfUtils.GetLuaScr(cell, UIFeelingCommunicationRoleNode)
    if scr then
        scr:Refresh(id, function()
            if checkNumber(self._curCatId) ~= checkNumber(id) then
                self:OnSelectCat(index)
            end
        end, index)

        --播放选中动画
        if checkNumber(self._curCatId) == checkNumber(id) then
            scr:PlaySelectAnimator()
            self:OnSelectCat(index)
        else
            scr:PlayUnSelectAnimator()
        end
    end

    return cell
end

--选择一个角色
function UIFeelingCommunicationDialog:OnSelectCat(index)
    index = checkNumber(index)
    self:ClearCatTalkCountRedPoint(self._allCats[index + 1])

    local lastInd = checkNumber(table.keyof(self._allCats, checkString(self._curCatId)))
    local go = self.LoopViewmessage:GetShownItemByItemIndex(lastInd - 1)
    if go then
        local scr = CfUtils.GetLuaScr(go, UIFeelingCommunicationRoleNode)
        if scr then
            scr:RefreshUnSelect()
        end
    end
    self:RefreshCurMessageId(self._curCatId)

    self._curCatId = self._allCats[index + 1]
    go = self.LoopViewmessage:GetShownItemByItemIndex(index)
    if go then
        local scr = CfUtils.GetLuaScr(go, UIFeelingCommunicationRoleNode)
        if scr then
            scr:RefreshSelect()
        end
    end

    local scr = CfUtils.GetLuaScr(self.RightPanel, UIFeelingCommunicationRightNode)
    if scr then
        scr:Refresh(self._curCatId, self._pageState, self._targetTopicId)
    end
end

--跳过自动播放的动画
function UIFeelingCommunicationDialog:RefreshCurMessageId(catId)
    if not catId then
        return
    end

    local t = phoneComp:GetCatCurChatInfo(catId)
    if t then
        local id = PhoneUtils.GetStopMessageId(t.curMessageId)
        phoneComp:UpdateCatCurChatInfo(catId, nil, id)
    end
end

--清楚一个角色的小红点数据
function UIFeelingCommunicationDialog:ClearCatTalkCountRedPoint(catId)
    local t = GameUtils.GetRedPointLocalAllGoods(Constants.RedPointLocalKey.Goodkey, Constants.IDType.PhoneTalkContent)
    --如果有话题
    if table.count(t) > 0 then
        for k, v in pairs(t) do
            local vo = PhoneUtils.GetPhoneTalkContentVo(v)
            if vo then
                if checkNumber(vo.character) == checkNumber(catId) then 
                    GameUtils.UpdateReadPointLocalKey(Constants.RedPointLocalKey.Goodkey, v, 0)
                end
            end
        end
    end
end
 
--改变这个界面的状态
function UIFeelingCommunicationDialog:OnChageChatPageState(body)
    if not body then
        return
    end
    self:__init()
    self._pageState = checkNumber(body.pageState)
    if self._pageState == Constants.CHATSOURCE.LOOKHISTORY then
        self._curCatId = checkString(body.catId)
        self._targetTopicId = checkString(body.talkContentId)  
        self:InitData()
        self:FillSelf()
        CfUtils.RefreshTopCommon(function()
            UIModule.OpenDialog({ id = Constants.UITypeIds.UIFeelingMessageRecordDialog, parameters = {catId = self._curCatId}}, {
            })
        end)
    elseif self._pageState == Constants.CHATSOURCE.NORMAL then
        self._curCatId = checkString(body.catId)
        self:RefeshNormalSelf()
    end
end

--刷新界面回到正常状态
function UIFeelingCommunicationDialog:RefeshNormalSelf()
    self._pageState = Constants.CHATSOURCE.NORMAL
    self:InitData()
    self:FillSelf()
    CfUtils.RefreshTopCommon(nil)
end

function UIFeelingCommunicationDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        CfUtils.SetUICameraProjection(false)
        CfUtils.SetTopCommonActive(true, false)
    end))
    return coWait
end

function UIFeelingCommunicationDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if not isNull(self) then
            Events.RemoveListener(Constants.EventNames.ChageChatPageState, self.EventChageChatPageState)
        end
        PhoneUtils.UpdatePhoneMessageRedPointNum()

        CfUtils.SetUICameraProjection(true)
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIFeelingCommunicationDialog
